    public native void nativeOpenMobileRewardedAdLoaded(long);
    public native void nativeOpenMobileRewardedAdShown(long);
    public native void nativeOpenMobileRewardedAdEarned(long, int, java.lang.String);
    public native void nativeOpenMobileRewardedAdClosed(long);
    public native void nativeOpenMobileRewardedAdFailed(long, java.lang.String);
}
